def comps(g):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==0 and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==0 and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                out.append(comp)
    return out
